import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import Header from './components/Header';
import HeroSection from './components/HeroSection';
import SearchFilters from './components/SearchFilters';
import PropertyGrid from './components/PropertyGrid';
import FavouritesSidebar from './components/FavouritesSidebar';
import PropertyDetail from './components/PropertyDetail';
import Footer from './components/Footer';
import { useFavourites } from './hooks/useFavourites';
import propertiesData from './data/properties.json';
import './styles/main.css';

function App() {
  const [properties, setProperties] = useState([]);
  const [filteredProperties, setFilteredProperties] = useState([]);
  const [searchFilters, setSearchFilters] = useState({
    location: '',
    type: 'all',
    minPrice: '',
    maxPrice: '',
    bedrooms: '',
    searchQuery: ''
  });
  const [activeTab, setActiveTab] = useState('all');
  const { favourites, addFavourite, removeFavourite, clearFavourites } = useFavourites();

  useEffect(() => {
    // Load properties from JSON data
    setProperties(propertiesData.properties);
    setFilteredProperties(propertiesData.properties);
  }, []);

  const handleSearch = (filters) => {
    setSearchFilters(filters);
    
    let filtered = propertiesData.properties;
    
    if (filters.location) {
      filtered = filtered.filter(p => 
        p.location.toLowerCase().includes(filters.location.toLowerCase()) ||
        p.postcode.toLowerCase().includes(filters.location.toLowerCase())
      );
    }
    
    if (filters.type !== 'all') {
      filtered = filtered.filter(p => p.type.toLowerCase() === filters.type.toLowerCase());
    }
    
    if (filters.minPrice) {
      filtered = filtered.filter(p => p.price >= parseInt(filters.minPrice));
    }
    
    if (filters.maxPrice) {
      filtered = filtered.filter(p => p.price <= parseInt(filters.maxPrice));
    }
    
    if (filters.bedrooms) {
      filtered = filtered.filter(p => p.bedrooms >= parseInt(filters.bedrooms));
    }
    
    if (filters.searchQuery) {
      filtered = filtered.filter(p => 
        p.location.toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
        p.description.toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
        p.type.toLowerCase().includes(filters.searchQuery.toLowerCase())
      );
    }
    
    if (activeTab !== 'all') {
      if (activeTab === 'House' || activeTab === 'Flat') {
        filtered = filtered.filter(p => p.type === activeTab);
      } else {
        // For sale/rent tabs
        filtered = filtered.filter(p => 
          (activeTab === 'sale' && p.price > 100000) || // Assuming high price = sale
          (activeTab === 'rent' && p.price < 100000)   // Assuming low price = rent
        );
      }
    }
    
    setFilteredProperties(filtered);
  };

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    let filtered = properties;
    
    if (tab !== 'all') {
      if (tab === 'sale') {
        filtered = filtered.filter(p => p.price > 500000); // Sale properties
      } else if (tab === 'rent') {
        filtered = filtered.filter(p => p.price < 500000); // Rent properties
      } else {
        filtered = filtered.filter(p => p.type === tab);
      }
    }
    
    setFilteredProperties(filtered);
  };

  const clearFilters = () => {
    const emptyFilters = {
      location: '',
      type: 'all',
      minPrice: '',
      maxPrice: '',
      bedrooms: '',
      searchQuery: ''
    };
    setSearchFilters(emptyFilters);
    setActiveTab('all');
    setFilteredProperties(propertiesData.properties);
  };

  const handleAddFavourite = (propertyId) => {
    if (!favourites.includes(propertyId)) {
      addFavourite(propertyId);
    }
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <Router>
        <div className="app">
          <div className="gradient-bg"></div>
          
          <Header favourites={favourites} />
          
          <Routes>
            <Route path="/" element={
              <>
                <HeroSection />
                
                <div className="search-section">
                  <div className="container">
                    <SearchFilters 
                      onSearch={handleSearch}
                      onClear={clearFilters}
                      filters={searchFilters}
                    />
                  </div>
                </div>
                
                <main className="main-content">
                  <div className="container">
                    <div className="content-wrapper">
                      <div className="property-tabs">
                        <button 
                          className={`tab-btn ${activeTab === 'all' ? 'active' : ''}`}
                          onClick={() => handleTabChange('all')}
                        >
                          All Properties
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'sale' ? 'active' : ''}`}
                          onClick={() => handleTabChange('sale')}
                        >
                          For Sale
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'rent' ? 'active' : ''}`}
                          onClick={() => handleTabChange('rent')}
                        >
                          For Rent
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'House' ? 'active' : ''}`}
                          onClick={() => handleTabChange('House')}
                        >
                          Houses
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'Flat' ? 'active' : ''}`}
                          onClick={() => handleTabChange('Flat')}
                        >
                          Flats
                        </button>
                      </div>
                      
                      <div className="main-grid">
                        <div className="properties-section">
                          <PropertyGrid 
                            properties={filteredProperties}
                            favourites={favourites}
                            onToggleFavourite={handleAddFavourite}
                          />
                        </div>
                        
                        <div className="sidebar-section">
                          <FavouritesSidebar 
                            favourites={favourites}
                            properties={properties}
                            onRemoveFavourite={removeFavourite}
                            onClearFavourites={clearFavourites}
                            onAddFavourite={handleAddFavourite}
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                </main>
              </>
            } />
            
            <Route path="/property/:id" element={
              <PropertyDetail 
                properties={properties}
                favourites={favourites}
                onToggleFavourite={handleAddFavourite}
              />
            } />
          </Routes>
          
          <Footer />
        </div>
      </Router>
    </DndProvider>
  );
}

export default App;
